pub fn find_signal(signal_id: u16) -> Option<&'static SignalProfile> {
    SIGNAL_PROFILES
        .iter()
        .find(|profile| profile.signal_id == signal_id)
}

pub fn signal_bias(signal_id: u16) -> u32 {
    if let Some(profile) = find_signal(signal_id) {
        profile.route_mask ^ ((profile.approach_m as u32) << 8) ^ profile.maint_window as u32
    } else {
        (signal_id as u32).wrapping_mul(0x045d_9f3b)
    }
}
